	tag := h >> 48
	ins = -1
	for {
		v := s.slots[i]
		if v == 0 {
			if ins < 0 {
				ins = i
			}
			return -1, ins
		}
		if v == tomb {
			if ins < 0 {
				ins = i
			}
		} else if v>>48 == tag {
			if bytes.Equal(item(v&ptrMask).key(), key) {
				return i, ins
			}
		}
		i = (i + 1) & mask
	}
