func (s *shard) insert(ins int, h uint64, it item) {
	if s.slots[ins] == tomb {
		s.tombs--
	}
	s.slots[ins] = uint64(it) | (h>>48)<<48
	s.count++
	if it.exp() != 0 {
		s.nexp++
	}
	s.addUsed(s.cost(it))
}

func (s *shard) setExp(it item, e int64) {
	old := it.exp()
	if old == 0 && e != 0 {
		s.nexp++
	} else if old != 0 && e == 0 {
		s.nexp--
	}
	it.setExpRaw(e)
