	if it != 0 {
		if it.typ() == typStr && len(val) <= it.capacity() && it.cls() != clsBig {
			d := len(val) - it.vlen()
			it.setVlen(len(val))
			copy(it.val(), val)
			s.setExp(it, exp)
			s.addUsed(int64(d))
			return
		}
		nw := s.newItem(key, len(val), typStr, now)
		copy(nw.val(), val)
		nw.setExpRaw(exp)
		s.replace(idx, it, nw)
		return
	}
	nw := s.newItem(key, len(val), typStr, now)
	copy(nw.val(), val)
	nw.setExpRaw(exp)
	s.insert(ins, h, nw)
}

func (s *shard) newContainer(ins int, h uint64, key []byte, typ uint8, o any, now int64) item {
	it := s.newItem(key, 4, typ, now)
	it.setObjIdx(s.newObj(o))
	s.insert(ins, h, it)
	return it
}

func (s *shard) flush() {
	for _, v := range s.slots {
		if v > tomb {
			it := item(v & ptrMask)
			if it.cls() == clsBig {
				s.freeItem(it)
			}
		}
	}
	s.addUsed(-s.used)
	s.slots = make([]uint64, 8)
	s.count, s.tombs, s.nexp, s.expCur = 0, 0, 0, 0
	s.free = [80]uintptr{}
	s.bumps = [80]bump{}
	s.objs = nil
	s.freeObjs = nil
}

// ---------------------------------------------------------------- expiry

func expiryLoop() {
	t := time.NewTicker(100 * time.Millisecond)
	for range t.C {
		for i := range shards {
			s := &shards[i]
			s.mu.Lock()
			if s.nexp == 0 {
				if s.count*8 < len(s.slots) && len(s.slots) > 64 {
					s.grow0()
				}
				s.mu.Unlock()
				continue
			}
			budget := len(s.slots)/8 + 64
			for budget > 0 {
				now := time.Now().UnixMilli()
				for n := 0; n < 1024 && budget > 0; n++ {
					budget--
					if s.expCur >= len(s.slots) {
						s.expCur = 0
					}
					v := s.slots[s.expCur]
					if v > tomb {
						it := item(v & ptrMask)
						if e := it.exp(); e != 0 && e <= now {
							s.del(s.expCur, it)
						}
					}
					s.expCur++
				}
				if s.count*8 < len(s.slots) && len(s.slots) > 64 {
					s.grow0()
				}
				s.mu.Unlock()
				s.mu.Lock()
			}
			s.mu.Unlock()
		}
	}
}

// grow0 shrinks the table to fit the current count.
func (s *shard) grow0() {
	n := 8
	for n*3 < (s.count+1)*4*2 {
		n *= 2
	}
	s.rehash(n)
}

// ---------------------------------------------------------------- eviction

func evict(protect [][]byte) {
	for globalUsed.Load() > maxMemory {
		if !evictOne(protect) {
			return
		}
	}
}

func isProtected(k []byte, protect [][]byte) bool {
	for _, p := range protect {
		if bytes.Equal(k, p) {
			return true
		}
	}
	return false
}

func evictOne(protect [][]byte) bool {
	for tries := 0; tries < nShards*4; tries++ {
		s := &shards[rand.IntN(nShards)]
		s.mu.Lock()
		if s.count == 0 {
			s.mu.Unlock()
			continue
		}
		n := len(s.slots)
		mask := n - 1
		i := rand.IntN(n)
		best := -1
		var bestLRU uint32
		var bestIt item
		sampled := 0
		for scanned := 0; scanned < n && sampled < 16; scanned++ {
			v := s.slots[i]
			if v > tomb {
				it := item(v & ptrMask)
				if !isProtected(it.key(), protect) {
					sampled++
					if l := it.lru(); best < 0 || l < bestLRU {
						best, bestLRU, bestIt = i, l, it
					}
				}
			}
			i = (i + 1) & mask
		}
		if best >= 0 {
			s.del(best, bestIt)
			s.mu.Unlock()
			return true
		}
		s.mu.Unlock()
	}
	return false
}

