func cmdDel(c *client, a [][]byte) {
	keys := a[1:]
	c.lockKeys(keys, 1)
	n := 0
	for i, k := range keys {
		h := c.hs[i]
		s := shardOf(h)
		idx, it, _ := s.get(k, h, c.now)
		if it != 0 {
			s.del(idx, it)
			n++
		}
	}
	c.unlockKeys()
	c.addInt(int64(n))
}

func cmdExists(c *client, a [][]byte) {
	keys := a[1:]
	c.lockKeys(keys, 1)
	n := 0
	for i, k := range keys {
		h := c.hs[i]
		if _, it, _ := shardOf(h).get(k, h, c.now); it != 0 {
			n++
		}
	}
