	c.addInt(int64(n))
}

func cmdType(c *client, a [][]byte) {
	h := hashKey(a[1])
	s := shardOf(h)
	s.mu.Lock()
	_, it, _ := s.get(a[1], h, c.now)
	t := "none"
	if it != 0 {
		t = [...]string{"string", "list", "hash"}[it.typ()]
	}
	s.mu.Unlock()
	c.addSimple(t)
}

func cmdExpire(c *client, a [][]byte, unit int64, name string) {
	v, ok := parseInt(a[2])
	if !ok {
		c.addErr(errNotInt)
		return
	}
	if v > math.MaxInt64/unit || v < math.MinInt64/unit {
		c.addErr("ERR invalid expire time in '" + name + "' command")
		return
	}
	v *= unit
	if (v > 0 && v > math.MaxInt64-c.now) || (v < 0 && c.now+v > c.now) {
		c.addErr("ERR invalid expire time in '" + name + "' command")
		return
	}
	when := c.now + v
	h := hashKey(a[1])
	s := shardOf(h)
	s.mu.Lock()
	idx, it, _ := s.get(a[1], h, c.now)
	if it == 0 {
		s.mu.Unlock()
		c.addInt(0)
		return
	}
	if when <= c.now {
		s.del(idx, it)
	} else {
		s.setExp(it, when)
	}
	s.mu.Unlock()
	c.addInt(1)
}

func cmdTTL(c *client, a [][]byte, secs bool) {
	h := hashKey(a[1])
	s := shardOf(h)
	s.mu.Lock()
	_, it, _ := s.get(a[1], h, c.now)
	var r int64
	switch {
	case it == 0:
		r = -2
	case it.exp() == 0:
		r = -1
	default:
		r = it.exp() - c.now
		if r < 0 {
			r = 0
		}
		if secs {
			r = (r + 500) / 1000
		}
	}
	s.mu.Unlock()
	c.addInt(r)
}

func cmdPersist(c *client, a [][]byte) {
	h := hashKey(a[1])
	s := shardOf(h)
	s.mu.Lock()
	_, it, _ := s.get(a[1], h, c.now)
	r := int64(0)
	if it != 0 && it.exp() != 0 {
		s.setExp(it, 0)
		r = 1
	}
	s.mu.Unlock()
	c.addInt(r)
}

func cmdKeys(c *client, a [][]byte) {
	pat := a[1]
	var out []byte
	n := 0
	for i := range shards {
		s := &shards[i]
		s.mu.Lock()
		for _, v := range s.slots {
			if v > tomb {
				it := item(v & ptrMask)
				if e := it.exp(); e != 0 && e <= c.now {
					continue
				}
				k := it.key()
				if globMatch(pat, k) {
					out = append(out, '$')
					out = strconv.AppendInt(out, int64(len(k)), 10)
					out = append(out, '\r', '\n')
					out = append(out, k...)
					out = append(out, '\r', '\n')
					n++
				}
			}
		}
		s.mu.Unlock()
	}
	c.addArr(n)
	c.out = append(c.out, out...)
}

// globMatch is a port of Redis' stringmatchlen.
func globMatch(p, s []byte) bool {
	pi, si := 0, 0
	for pi < len(p) && si < len(s) {
		switch p[pi] {
		case '*':
			for pi+1 < len(p) && p[pi+1] == '*' {
				pi++
			}
			if pi+1 == len(p) {
				return true
			}
			for si < len(s) {
				if globMatch(p[pi+1:], s[si:]) {
					return true
				}
				si++
			}
			return false
		case '?':
		case '[':
			pi++
			not := pi < len(p) && p[pi] == '^'
			if not {
				pi++
			}
			match := false
			for {
				if pi+1 < len(p) && p[pi] == '\\' {
					pi++
					if p[pi] == s[si] {
						match = true
					}
				} else if pi >= len(p) {
					pi--
					break
				} else if p[pi] == ']' {
					break
				} else if pi+2 < len(p) && p[pi+1] == '-' {
					lo, hi := p[pi], p[pi+2]
					if lo > hi {
						lo, hi = hi, lo
					}
					if s[si] >= lo && s[si] <= hi {
						match = true
					}
					pi += 2
				} else if p[pi] == s[si] {
					match = true
				}
				pi++
			}
			if not {
				match = !match
			}
			if !match {
				return false
			}
		case '\\':
			if pi+1 < len(p) {
				pi++
			}
			if p[pi] != s[si] {
				return false
			}
		default:
			if p[pi] != s[si] {
				return false
			}
		}
		pi++
		si++
		if si == len(s) {
			for pi < len(p) && p[pi] == '*' {
				pi++
			}
			break
		}
	}
	return pi == len(p) && si == len(s)
}

// ---------------------------------------------------------------- lists

func (l *listObj) resize(n int) {
	nb := make([]string, n)
	for i := 0; i < l.n; i++ {
		nb[i] = l.buf[(l.head+i)&(len(l.buf)-1)]
	}
	l.buf, l.head = nb, 0
}

func (l *listObj) at(i int) string { return l.buf[(l.head+i)&(len(l.buf)-1)] }

func (l *listObj) push(v string, front bool) {
	if l.n == len(l.buf) {
		l.resize(max(4, len(l.buf)*2))
	}
	mask := len(l.buf) - 1
	if front {
		l.head = (l.head - 1) & mask
		l.buf[l.head] = v
	} else {
		l.buf[(l.head+l.n)&mask] = v
	}
	l.n++
}

func (l *listObj) pop(front bool) string {
	mask := len(l.buf) - 1
	var i int
	if front {
		i = l.head
		l.head = (l.head + 1) & mask
	} else {
		i = (l.head + l.n - 1) & mask
	}
	v := l.buf[i]
	l.buf[i] = ""
	l.n--
	if len(l.buf) > 16 && l.n < len(l.buf)/4 {
		l.resize(len(l.buf) / 2)
	}
	return v
}

func cmdPush(c *client, a [][]byte, front bool) {
	key := a[1]
	h := hashKey(key)
	s := shardOf(h)
	s.mu.Lock()
	s.grow()
	_, it, ins := s.get(key, h, c.now)
	if it != 0 && it.typ() != typList {
		s.mu.Unlock()
		c.addErr(errWrongType)
		return
	}
	var delta int64
	for _, v := range a[2:] {
		delta += int64(16 + len(v))
	}
	if maxMemory > 0 {
		cur := int64(64 + len(key))
		if it != 0 {
			cur = s.cost(it)
		}
		if cur+delta > maxMemory {
			s.mu.Unlock()
			c.addErr(errOOM)
			return
		}
	}
	var l *listObj
	if it == 0 {
		l = &listObj{}
		s.newContainer(ins, h, key, typList, l, c.now)
	} else {
		l = s.objs[it.objIdx()].(*listObj)
	}
	for _, v := range a[2:] {
		l.push(string(v), front)
	}
	l.cost += delta
	s.addUsed(delta)
	n := l.n
	s.mu.Unlock()
	c.addInt(int64(n))
	c.afterWrite(key)
}

func cmdPop(c *client, a [][]byte, front bool) {
	if len(a) > 3 {
		c.addErr("ERR wrong number of arguments for '" + [...]string{"rpop", "lpop"}[b2i(front)] + "' command")
		return
	}
	count := int64(-1)
	if len(a) == 3 {
		v, ok := parseInt(a[2])
		if !ok || v < 0 {
			c.addErr(errPositive)
			return
		}
		count = v
	}
	h := hashKey(a[1])
	s := shardOf(h)
	s.mu.Lock()
	idx, it, _ := s.get(a[1], h, c.now)
	if it == 0 {
		s.mu.Unlock()
		if count >= 0 {
			c.addNullArr()
		} else {
			c.addNull()
		}
		return
	}
	if it.typ() != typList {
		s.mu.Unlock()
		c.addErr(errWrongType)
		return
	}
	l := s.objs[it.objIdx()].(*listObj)
	var delta int64
	if count < 0 {
		v := l.pop(front)
		delta += int64(16 + len(v))
		c.addBulkStr(v)
	} else {
		n := int(min(count, int64(l.n)))
		c.addArr(n)
		for i := 0; i < n; i++ {
			v := l.pop(front)
			delta += int64(16 + len(v))
			c.addBulkStr(v)
		}
	}
	l.cost -= delta
	s.addUsed(-delta)
	if l.n == 0 {
		s.del(idx, it)
	}
	s.mu.Unlock()
}

func b2i(b bool) int {
	if b {
		return 1
	}
	return 0
}

func (s *shard) getList(c *client, key []byte) (*listObj, bool) {
	h := hashKey(key)
	_ = s
	return nil, false
}

// lookupTyped locks the key's shard and returns the item if it has type typ.
// On a type mismatch it writes WRONGTYPE and returns ok=false. The caller must
// unlock s when ok is true.
func lookupTyped(c *client, key []byte, typ uint8) (s *shard, idx int, it item, ok bool) {
	h := hashKey(key)
	s = shardOf(h)
	s.mu.Lock()
	idx, it, _ = s.get(key, h, c.now)
	if it != 0 && it.typ() != typ {
		s.mu.Unlock()
		c.addErr(errWrongType)
		return nil, 0, 0, false
	}
	return s, idx, it, true
}

func cmdLlen(c *client, a [][]byte) {
	s, _, it, ok := lookupTyped(c, a[1], typList)
	if !ok {
		return
	}
	n := 0
	if it != 0 {
		n = s.objs[it.objIdx()].(*listObj).n
	}
	s.mu.Unlock()
	c.addInt(int64(n))
}

func cmdLrange(c *client, a [][]byte) {
	start, ok1 := parseInt(a[2])
	stop, ok2 := parseInt(a[3])
	if !ok1 || !ok2 {
		c.addErr(errNotInt)
		return
	}
	s, _, it, ok := lookupTyped(c, a[1], typList)
	if !ok {
		return
	}
	if it == 0 {
		s.mu.Unlock()
		c.addArr(0)
		return
	}
	l := s.objs[it.objIdx()].(*listObj)
	n := int64(l.n)
	if start < 0 {
		start += n
	}
	if stop < 0 {
		stop += n
	}
	if start < 0 {
		start = 0
	}
	if start > stop || start >= n {
		s.mu.Unlock()
		c.addArr(0)
		return
	}
	if stop >= n {
		stop = n - 1
	}
	c.addArr(int(stop - start + 1))
	for i := start; i <= stop; i++ {
		c.addBulkStr(l.at(int(i)))
	}
	s.mu.Unlock()
}

func cmdLindex(c *client, a [][]byte) {
	idx, ok := parseInt(a[2])
	if !ok {
		c.addErr(errNotInt)
		return
	}
	s, _, it, ok := lookupTyped(c, a[1], typList)
	if !ok {
		return
	}
	if it == 0 {
		s.mu.Unlock()
		c.addNull()
		return
	}
	l := s.objs[it.objIdx()].(*listObj)
	if idx < 0 {
		idx += int64(l.n)
	}
	if idx < 0 || idx >= int64(l.n) {
		c.addNull()
	} else {
		c.addBulkStr(l.at(int(idx)))
	}
	s.mu.Unlock()
}

// ---------------------------------------------------------------- hashes

func cmdHset(c *client, a [][]byte) {
	if len(a)%2 != 0 {
		c.addErr("ERR wrong number of arguments for '" + strings.ToLower(string(a[0])) + "' command")
		return
	}
	key := a[1]
	h := hashKey(key)
	s := shardOf(h)
	s.mu.Lock()
	s.grow()
	_, it, ins := s.get(key, h, c.now)
	if it != 0 && it.typ() != typHash {
		s.mu.Unlock()
		c.addErr(errWrongType)
		return
	}
	if maxMemory > 0 {
		cur := int64(64 + len(key))
		if it != 0 {
			cur = s.cost(it)
		}
		for i := 2; i < len(a); i += 2 {
			cur += int64(32 + len(a[i]) + len(a[i+1]))
		}
		if cur > maxMemory {
			s.mu.Unlock()
			c.addErr(errOOM)
			return
		}
	}
	var ho *hashObj
	if it == 0 {
		ho = &hashObj{m: make(map[string]string, (len(a)-2)/2)}
		s.newContainer(ins, h, key, typHash, ho, c.now)
	} else {
		ho = s.objs[it.objIdx()].(*hashObj)
	}
	var delta int64
	added := 0
	for i := 2; i < len(a); i += 2 {
		f, v := a[i], a[i+1]
		if old, ok := ho.m[string(f)]; ok {
			delta += int64(len(v) - len(old))
			ho.m[string(f)] = string(v)
		} else {
			delta += int64(32 + len(f) + len(v))
			ho.m[string(f)] = string(v)
			added++
		}
	}
	ho.cost += delta
	s.addUsed(delta)
	s.mu.Unlock()
	c.addInt(int64(added))
	c.afterWrite(key)
}

func cmdHget(c *client, a [][]byte) {
	s, _, it, ok := lookupTyped(c, a[1], typHash)
	if !ok {
		return
	}
	if it == 0 {
		c.addNull()
	} else if v, ok := s.objs[it.objIdx()].(*hashObj).m[string(a[2])]; ok {
		c.addBulkStr(v)
	} else {
		c.addNull()
	}
	s.mu.Unlock()
}

func cmdHdel(c *client, a [][]byte) {
	s, idx, it, ok := lookupTyped(c, a[1], typHash)
	if !ok {
		return
	}
	n := 0
	if it != 0 {
		ho := s.objs[it.objIdx()].(*hashObj)
		var delta int64
		for _, f := range a[2:] {
			if old, ok := ho.m[string(f)]; ok {
				delete(ho.m, string(f))
				delta += int64(32 + len(f) + len(old))
				n++
			}
		}
		ho.cost -= delta
		s.addUsed(-delta)
		if len(ho.m) == 0 {
			s.del(idx, it)
		}
	}
	s.mu.Unlock()
	c.addInt(int64(n))
}

func cmdHgetall(c *client, a [][]byte) {
	s, _, it, ok := lookupTyped(c, a[1], typHash)
	if !ok {
		return
	}
	if it == 0 {
		c.addArr(0)
	} else {
		ho := s.objs[it.objIdx()].(*hashObj)
		c.addArr(len(ho.m) * 2)
		for f, v := range ho.m {
			c.addBulkStr(f)
			c.addBulkStr(v)
		}
	}
	s.mu.Unlock()
}

func cmdHlen(c *client, a [][]byte) {
	s, _, it, ok := lookupTyped(c, a[1], typHash)
	if !ok {
		return
	}
	n := 0
	if it != 0 {
		n = len(s.objs[it.objIdx()].(*hashObj).m)
	}
	s.mu.Unlock()
	c.addInt(int64(n))
}

func cmdHexists(c *client, a [][]byte) {
	s, _, it, ok := lookupTyped(c, a[1], typHash)
	if !ok {
		return
	}
	n := 0
	if it != 0 {
		if _, ok := s.objs[it.objIdx()].(*hashObj).m[string(a[2])]; ok {
			n = 1
		}
	}
	s.mu.Unlock()
	c.addInt(int64(n))
}

func cmdHincrby(c *client, a [][]byte) {
	delta, ok := parseInt(a[3])
	if !ok {
		c.addErr(errNotInt)
		return
	}
	key, f := a[1], a[2]
	h := hashKey(key)
	s := shardOf(h)
	s.mu.Lock()
	s.grow()
	_, it, ins := s.get(key, h, c.now)
	if it != 0 && it.typ() != typHash {
		s.mu.Unlock()
		c.addErr(errWrongType)
		return
	}
	var ho *hashObj
	var cur int64
	var old string
	exists := false
	if it != 0 {
		ho = s.objs[it.objIdx()].(*hashObj)
		if old, exists = ho.m[string(f)]; exists {
			v, ok := parseInt([]byte(old))
			if !ok {
				s.mu.Unlock()
				c.addErr(errHashInt)
				return
			}
			cur = v
		}
	}
	if (delta > 0 && cur > math.MaxInt64-delta) || (delta < 0 && cur < math.MinInt64-delta) {
		s.mu.Unlock()
		c.addErr(errOverflow)
		return
	}
	cur += delta
	nv := strconv.FormatInt(cur, 10)
	if maxMemory > 0 {
		est := int64(64+len(key)+32+len(f)+len(nv))
		if it != 0 {
			est += s.cost(it)
		}
		if est > maxMemory {
			s.mu.Unlock()
			c.addErr(errOOM)
			return
		}
	}
	if ho == nil {
		ho = &hashObj{m: make(map[string]string, 1)}
		s.newContainer(ins, h, key, typHash, ho, c.now)
	}
	var d int64
	if exists {
		d = int64(len(nv) - len(old))
	} else {
		d = int64(32 + len(f) + len(nv))
	}
	ho.m[string(f)] = nv
	ho.cost += d
	s.addUsed(d)
	s.mu.Unlock()
	c.addInt(cur)
	c.afterWrite(key)
}

