+	s.mu.Unlock()
+}
+
+func cmdSet(c *client, a [][]byte) {
+	var nx, xx, get, keep, hasExp bool
+	var exp int64
+	for i := 3; i < len(a); i++ {
+		o := a[i]
+		switch {
+		case eqFold(o, "NX") && !xx:
+			nx = true
+		case eqFold(o, "XX") && !nx:
+			xx = true
+		case eqFold(o, "GET"):
+			get = true
+		case eqFold(o, "KEEPTTL") && !hasExp:
+			keep = true
+		case (eqFold(o, "EX") || eqFold(o, "PX")) && !keep && !hasExp && i+1 < len(a):
+			v, ok := parseInt(a[i+1])
+			if !ok {
+				c.addErr(errNotInt)
+				return
+			}
+			if v <= 0 {
+				c.addErr("ERR invalid expire time in 'set' command")
+				return
+			}
+			if o[0] == 'E' || o[0] == 'e' {
+				if v > math.MaxInt64/1000 {
+					c.addErr("ERR invalid expire time in 'set' command")
+					return
+				}
+				v *= 1000
+			}
+			if v > math.MaxInt64-c.now {
+				c.addErr("ERR invalid expire time in 'set' command")
+				return
+			}
+			exp = c.now + v
+			hasExp = true
+			i++
+		default:
+			c.addErr(errSyntax)
+			return
+		}
+	}
+	key, val := a[1], a[2]
+	if maxMemory > 0 && int64(64+len(key)+len(val)) > maxMemory {
+		c.addErr(errOOM)
+		return
+	}
+	h := hashKey(key)
+	s := shardOf(h)
+	s.mu.Lock()
+	s.grow()
+	idx, it, ins := s.get(key, h, c.now)
+	if get && it != 0 && it.typ() != typStr {
+		s.mu.Unlock()
+		c.addErr(errWrongType)
+		return
+	}
+	if (nx && it != 0) || (xx && it == 0) {
+		if get && it != 0 {
+			c.addBulk(it.val())
+		} else {
+			c.addNull()
+		}
+		s.mu.Unlock()
+		return
+	}
+	if get {
+		if it != 0 {
+			c.addBulk(it.val())
+		} else {
+			c.addNull()
+		}
+	}
+	if keep && it != 0 {
+		exp = it.exp()
+	}
+	s.setStr(idx, it, ins, h, key, val, exp, c.now)
+	s.mu.Unlock()
+	if !get {
+		c.addOK()
+	}
+	c.afterWrite(key)
+}
+
+func cmdMget(c *client, a [][]byte) {
+	keys := a[1:]
+	c.lockKeys(keys, 1)
+	c.addArr(len(keys))
+	for i, k := range keys {
+		h := c.hs[i]
+		_, it, _ := shardOf(h).get(k, h, c.now)
+		if it == 0 || it.typ() != typStr {
+			c.addNull()
+		} else {
+			c.addBulk(it.val())
+		}
+	}
+	c.unlockKeys()
+}
