+func cmdMset(c *client, a [][]byte) {
+	if (len(a)-1)%2 != 0 {
+		c.addErr("ERR wrong number of arguments for 'mset' command")
+		return
+	}
+	if maxMemory > 0 {
+		var total int64
+		for i := 1; i < len(a); i += 2 {
+			total += int64(64 + len(a[i]) + len(a[i+1]))
+		}
+		if total > maxMemory {
+			c.addErr(errOOM)
+			return
+		}
+	}
+	c.lockKeys(a[1:], 2)
+	for i := 1; i < len(a); i += 2 {
+		h := c.hs[(i-1)/2]
+		s := shardOf(h)
+		s.grow()
+		idx, it, ins := s.get(a[i], h, c.now)
+		s.setStr(idx, it, ins, h, a[i], a[i+1], 0, c.now)
+	}
+	c.unlockKeys()
+	c.addOK()
+	if maxMemory > 0 {
+		c.keys = c.keys[:0]
+		for i := 1; i < len(a); i += 2 {
+			c.keys = append(c.keys, a[i])
+		}
+		c.afterWrite(c.keys...)
+	}
+}
