+func incrBy(c *client, key []byte, delta int64) {
+	h := hashKey(key)
+	s := shardOf(h)
+	s.mu.Lock()
+	s.grow()
+	idx, it, ins := s.get(key, h, c.now)
+	var cur, exp int64
+	if it != 0 {
+		if it.typ() != typStr {
+			s.mu.Unlock()
+			c.addErr(errWrongType)
+			return
+		}
+		v, ok := parseInt(it.val())
+		if !ok {
+			s.mu.Unlock()
+			c.addErr(errNotInt)
+			return
+		}
+		cur, exp = v, it.exp()
+	}
+	if (delta > 0 && cur > math.MaxInt64-delta) || (delta < 0 && cur < math.MinInt64-delta) {
+		s.mu.Unlock()
+		c.addErr(errOverflow)
+		return
+	}
+	cur += delta
+	c.num = strconv.AppendInt(c.num[:0], cur, 10)
+	s.setStr(idx, it, ins, h, key, c.num, exp, c.now)
+	s.mu.Unlock()
+	c.addInt(cur)
+	c.afterWrite(key)
+}
+
+func cmdAppend(c *client, a [][]byte) {
+	key, v := a[1], a[2]
+	h := hashKey(key)
+	s := shardOf(h)
+	s.mu.Lock()
+	s.grow()
+	idx, it, ins := s.get(key, h, c.now)
+	if it == 0 {
+		if maxMemory > 0 && int64(64+len(key)+len(v)) > maxMemory {
+			s.mu.Unlock()
+			c.addErr(errOOM)
+			return
+		}
+		s.setStr(idx, it, ins, h, key, v, 0, c.now)
+		s.mu.Unlock()
+		c.addInt(int64(len(v)))
+		c.afterWrite(key)
+		return
+	}
+	if it.typ() != typStr {
+		s.mu.Unlock()
+		c.addErr(errWrongType)
+		return
+	}
+	ol := it.vlen()
+	nl := ol + len(v)
+	if maxMemory > 0 && int64(64+len(key)+nl) > maxMemory {
+		s.mu.Unlock()
+		c.addErr(errOOM)
+		return
+	}
+	if nl <= it.capacity() && it.cls() != clsBig {
+		copy(it.valN(nl)[ol:], v)
+		it.setVlen(nl)
+		s.addUsed(int64(len(v)))
+	} else {
+		// grow with headroom so repeated appends are amortized
+		capN := nl + nl/4
+		nw := s.newItem(key, capN, typStr, c.now)
+		nw.setVlen(nl)
+		copy(nw.val(), it.val())
+		copy(nw.val()[ol:], v)
+		nw.setExpRaw(it.exp())
+		s.replace(idx, it, nw)
+	}
+	s.mu.Unlock()
+	c.addInt(int64(nl))
+	c.afterWrite(key)
+}
+
+func cmdStrlen(c *client, a [][]byte) {
+	h := hashKey(a[1])
+	s := shardOf(h)
+	s.mu.Lock()
+	_, it, _ := s.get(a[1], h, c.now)
+	if it == 0 {
+		c.addInt(0)
+	} else if it.typ() != typStr {
+		c.addErr(errWrongType)
+	} else {
+		c.addInt(int64(it.vlen()))
+	}
+	s.mu.Unlock()
+}
