+func cmdExpire(c *client, a [][]byte, unit int64, name string) {
+	v, ok := parseInt(a[2])
+	if !ok {
+		c.addErr(errNotInt)
+		return
+	}
+	if v > math.MaxInt64/unit || v < math.MinInt64/unit {
+		c.addErr("ERR invalid expire time in '" + name + "' command")
+		return
+	}
+	v *= unit
+	if (v > 0 && v > math.MaxInt64-c.now) || (v < 0 && c.now+v > c.now) {
+		c.addErr("ERR invalid expire time in '" + name + "' command")
+		return
+	}
+	when := c.now + v
+	h := hashKey(a[1])
+	s := shardOf(h)
+	s.mu.Lock()
+	idx, it, _ := s.get(a[1], h, c.now)
+	if it == 0 {
+		s.mu.Unlock()
+		c.addInt(0)
+		return
+	}
+	if when <= c.now {
+		s.del(idx, it)
+	} else {
+		s.setExp(it, when)
+	}
+	s.mu.Unlock()
+	c.addInt(1)
+}
+
+func cmdTTL(c *client, a [][]byte, secs bool) {
+	h := hashKey(a[1])
+	s := shardOf(h)
+	s.mu.Lock()
+	_, it, _ := s.get(a[1], h, c.now)
+	var r int64
+	switch {
+	case it == 0:
+		r = -2
+	case it.exp() == 0:
+		r = -1
+	default:
+		r = it.exp() - c.now
+		if r < 0 {
+			r = 0
+		}
+		if secs {
+			r = (r + 500) / 1000
+		}
+	}
+	s.mu.Unlock()
+	c.addInt(r)
+}
