+func cmdPersist(c *client, a [][]byte) {
+	h := hashKey(a[1])
+	s := shardOf(h)
+	s.mu.Lock()
+	_, it, _ := s.get(a[1], h, c.now)
+	r := int64(0)
+	if it != 0 && it.exp() != 0 {
+		s.setExp(it, 0)
+		r = 1
+	}
+	s.mu.Unlock()
+	c.addInt(r)
+}
+
+func cmdKeys(c *client, a [][]byte) {
+	pat := a[1]
+	var out []byte
+	n := 0
+	for i := range shards {
+		s := &shards[i]
+		s.mu.Lock()
+		for _, v := range s.slots {
+			if v > tomb {
+				it := item(v & ptrMask)
+				if e := it.exp(); e != 0 && e <= c.now {
+					continue
+				}
+				k := it.key()
+				if globMatch(pat, k) {
+					out = append(out, '$')
+					out = strconv.AppendInt(out, int64(len(k)), 10)
+					out = append(out, '\r', '\n')
+					out = append(out, k...)
+					out = append(out, '\r', '\n')
+					n++
+				}
+			}
+		}
+		s.mu.Unlock()
+	}
+	c.addArr(n)
+	c.out = append(c.out, out...)
+}
+
+// globMatch is a port of Redis' stringmatchlen.
+func globMatch(p, s []byte) bool {
+	pi, si := 0, 0
+	for pi < len(p) && si < len(s) {
+		switch p[pi] {
+		case '*':
+			for pi+1 < len(p) && p[pi+1] == '*' {
+				pi++
+			}
+			if pi+1 == len(p) {
+				return true
+			}
+			for si < len(s) {
+				if globMatch(p[pi+1:], s[si:]) {
+					return true
+				}
+				si++
+			}
+			return false
+		case '?':
+		case '[':
+			pi++
+			not := pi < len(p) && p[pi] == '^'
+			if not {
+				pi++
+			}
+			match := false
+			for {
+				if pi+1 < len(p) && p[pi] == '\\' {
+					pi++
+					if p[pi] == s[si] {
+						match = true
+					}
+				} else if pi >= len(p) {
+					pi--
+					break
+				} else if p[pi] == ']' {
+					break
+				} else if pi+2 < len(p) && p[pi+1] == '-' {
+					lo, hi := p[pi], p[pi+2]
+					if lo > hi {
+						lo, hi = hi, lo
+					}
+					if s[si] >= lo && s[si] <= hi {
+						match = true
+					}
+					pi += 2
+				} else if p[pi] == s[si] {
+					match = true
+				}
+				pi++
+			}
+			if not {
+				match = !match
+			}
+			if !match {
+				return false
+			}
+		case '\\':
+			if pi+1 < len(p) {
+				pi++
+			}
+			if p[pi] != s[si] {
+				return false
+			}
+		default:
+			if p[pi] != s[si] {
+				return false
+			}
+		}
+		pi++
+		si++
+		if si == len(s) {
+			for pi < len(p) && p[pi] == '*' {
+				pi++
+			}
+			break
+		}
+	}
+	return pi == len(p) && si == len(s)
+}
