+// ---------------------------------------------------------------- lists
+
+func (l *listObj) resize(n int) {
+	nb := make([]string, n)
+	for i := 0; i < l.n; i++ {
+		nb[i] = l.buf[(l.head+i)&(len(l.buf)-1)]
+	}
+	l.buf, l.head = nb, 0
+}
+
+func (l *listObj) at(i int) string { return l.buf[(l.head+i)&(len(l.buf)-1)] }
+
+func (l *listObj) push(v string, front bool) {
+	if l.n == len(l.buf) {
+		l.resize(max(4, len(l.buf)*2))
+	}
+	mask := len(l.buf) - 1
+	if front {
+		l.head = (l.head - 1) & mask
+		l.buf[l.head] = v
+	} else {
+		l.buf[(l.head+l.n)&mask] = v
+	}
+	l.n++
+}
+
+func (l *listObj) pop(front bool) string {
+	mask := len(l.buf) - 1
+	var i int
+	if front {
+		i = l.head
+		l.head = (l.head + 1) & mask
+	} else {
+		i = (l.head + l.n - 1) & mask
+	}
+	v := l.buf[i]
+	l.buf[i] = ""
+	l.n--
+	if len(l.buf) > 16 && l.n < len(l.buf)/4 {
+		l.resize(len(l.buf) / 2)
+	}
+	return v
+}
+
+func cmdPush(c *client, a [][]byte, front bool) {
+	key := a[1]
+	h := hashKey(key)
+	s := shardOf(h)
+	s.mu.Lock()
+	s.grow()
+	_, it, ins := s.get(key, h, c.now)
+	if it != 0 && it.typ() != typList {
+		s.mu.Unlock()
+		c.addErr(errWrongType)
+		return
+	}
+	var delta int64
+	for _, v := range a[2:] {
+		delta += int64(16 + len(v))
+	}
+	if maxMemory > 0 {
+		cur := int64(64 + len(key))
+		if it != 0 {
+			cur = s.cost(it)
+		}
+		if cur+delta > maxMemory {
+			s.mu.Unlock()
+			c.addErr(errOOM)
+			return
+		}
+	}
+	var l *listObj
+	if it == 0 {
+		l = &listObj{}
+		s.newContainer(ins, h, key, typList, l, c.now)
+	} else {
+		l = s.objs[it.objIdx()].(*listObj)
+	}
+	for _, v := range a[2:] {
+		l.push(string(v), front)
+	}
+	l.cost += delta
+	s.addUsed(delta)
+	n := l.n
+	s.mu.Unlock()
+	c.addInt(int64(n))
+	c.afterWrite(key)
+}
+
+func cmdPop(c *client, a [][]byte, front bool) {
+	if len(a) > 3 {
+		c.addErr("ERR wrong number of arguments for '" + [...]string{"rpop", "lpop"}[b2i(front)] + "' command")
+		return
+	}
+	count := int64(-1)
+	if len(a) == 3 {
+		v, ok := parseInt(a[2])
+		if !ok || v < 0 {
+			c.addErr(errPositive)
+			return
+		}
+		count = v
+	}
+	h := hashKey(a[1])
+	s := shardOf(h)
+	s.mu.Lock()
+	idx, it, _ := s.get(a[1], h, c.now)
+	if it == 0 {
+		s.mu.Unlock()
+		if count >= 0 {
+			c.addNullArr()
+		} else {
+			c.addNull()
+		}
+		return
+	}
+	if it.typ() != typList {
+		s.mu.Unlock()
+		c.addErr(errWrongType)
+		return
+	}
+	l := s.objs[it.objIdx()].(*listObj)
+	var delta int64
+	if count < 0 {
+		v := l.pop(front)
+		delta += int64(16 + len(v))
+		c.addBulkStr(v)
+	} else {
+		n := int(min(count, int64(l.n)))
+		c.addArr(n)
+		for i := 0; i < n; i++ {
+			v := l.pop(front)
+			delta += int64(16 + len(v))
+			c.addBulkStr(v)
+		}
+	}
+	l.cost -= delta
+	s.addUsed(-delta)
+	if l.n == 0 {
+		s.del(idx, it)
+	}
+	s.mu.Unlock()
+}
+
+func b2i(b bool) int {
+	if b {
+		return 1
+	}
+	return 0
+}
