// map once it grows past hashMaxFlat fields.
type hashObj struct {
	kv   []string
	m    map[string]string
	cost int64
}

const hashMaxFlat = 16

func (h *hashObj) get(f []byte) (string, bool) {
	if h.m != nil {
		v, ok := h.m[string(f)]
		return v, ok
	}
	for i := 0; i < len(h.kv); i += 2 {
		if h.kv[i] == string(f) {
			return h.kv[i+1], true
		}
	}
	return "", false
}

// set stores f=v and returns the previous value, if any.
func (h *hashObj) set(f []byte, v string) (string, bool) {
	if h.m != nil {
		old, ok := h.m[string(f)]
		h.m[string(f)] = v
		return old, ok
	}
	for i := 0; i < len(h.kv); i += 2 {
		if h.kv[i] == string(f) {
			old := h.kv[i+1]
			h.kv[i+1] = v
			return old, true
		}
	}
	if len(h.kv) >= hashMaxFlat*2 {
		h.m = make(map[string]string, len(h.kv))
		for i := 0; i < len(h.kv); i += 2 {
			h.m[h.kv[i]] = h.kv[i+1]
		}
		h.kv = nil
		h.m[string(f)] = v
		return "", false
	}
	h.kv = append(h.kv, string(f), v)
	return "", false
}

func (h *hashObj) del(f []byte) (string, bool) {
	if h.m != nil {
		old, ok := h.m[string(f)]
		if ok {
			delete(h.m, string(f))
		}
		return old, ok
	}
	for i := 0; i < len(h.kv); i += 2 {
		if h.kv[i] == string(f) {
			old := h.kv[i+1]
			n := len(h.kv)
			h.kv[i], h.kv[i+1] = h.kv[n-2], h.kv[n-1]
			h.kv[n-2], h.kv[n-1] = "", ""
			h.kv = h.kv[:n-2]
			return old, true
		}
	}
	return "", false
}

func (h *hashObj) size() int {
	if h.m != nil {
		return len(h.m)
	}
	return len(h.kv) / 2
}''')
